# Snapshot full current dependencies, exact source choices and authored checks below.
def pointer(doc,path):
 for part in path.strip('/').split('/'):
  doc=doc[int(part)] if isinstance(doc,list) else doc[part.replace('~1','/').replace('~0','~')]
 return doc

def main():
 out=R/'data/director/magic_core_feat_operating_proposal_internal.json'
 doc=R/'docs/feats/MAGIC_CORE_FEAT_OPERATING_PROPOSAL.md'
 receipt=A/'MAGIC_CORE_31_OPERATING_PROPOSAL_CHECK.json'
 draft=A/'MAGIC_CORE_31_OPERATING_PROPOSALS.json'
 assert not any(p.exists() for p in [out,doc,receipt,draft])
 prep=load(A/'MAGIC_CORE_FEAT_SOURCE_PREPARATION.json');sources={x['featId']:x for x in prep['selectedFeats']}
 registry=R/'src/data/feats.js'
 feats=json.JSONDecoder().raw_decode(registry.read_text('utf-8').split('export const feats = ',1)[1])[0];by={x['id']:x for x in feats}
 manifest=R/'data/public/feat_playtests/manifest.json';reviewed=set(load(manifest)['operationalIds'])
 catFile=R/'data/public/spell_playtests/catalog.json';cat=load(catFile);spells={x['id']:x for x in cat['spells']}
 indexFile=catFile.with_name('authored_review_index.json');idx=load(indexFile);entries={x['id']:x for x in idx['entries']}
 lowFile=catFile.with_name('candidate_low_rank_136.json');low=load(lowFile)
