 check('31 exact original identities',len(P)==31 and len({x['featId'] for x in P})==31 and {x['featId'] for x in P}==set(sources))
 check('335 original feats and8reviewed',len(feats)==len(by)==335 and len(reviewed)==8)
 check('848 ordinary source identities',len(spells)==848)
 check('412 current authored spells and436pending',idx['authoredCounts']=={'reviewed':412,'pending':436})
 check('Missing exact Spell Focus remains missing',not any(x['name'].casefold()=='spell focus' for x in feats))
 check('No original Detect Thoughts identity',not any(x['name'].casefold()=='detect thoughts' for x in spells.values()) and not any(x['name'].casefold()=='detect thoughts' for x in ancestry['spells']))
 ritualOriginal=[x['id'] for x in spells.values() if any('ritual' in [t.casefold() for t in e['original'].get('tags',[])] for e in x['source'].get('coreEntries',[]))]
 check('No explicit Ritual tag in scoped current Core arrays',ritualOriginal==[])
 records=[]
 for x in P:
  s=sources[x['featId']];fid=x['featId']
  check(fid+' exact original source',s['sourceObject']==by[fid]);check(fid+' remains pending',fid not in reviewed)
  check(fid+' authored fields and2cases',all(x.get(k) for k in ['procedure','newChoices','dependencies']) and len(x['workedCases'])==2)
  records.append({**x,'questionId':s['questionId'],'sourceObject':s['sourceObject'],'sourceObjectSha256':s['sourceObjectSha256'],'originalQuestion':s['fullClauseQuestion'],'status':'unadopted-feat-interface-proposal','authoredCasesAreRuntimeTests':False,'priorReviewedComponentCarried':fid=='familiar_bond'})
 records.sort(key=lambda x:x['questionId'])
 check('29 complete proposals plus2 deferred payload boundaries',sum(x['procedureScope']=='complete-proposed-feat' for x in records)==29 and sum(x['procedureScope']=='grant-interface-only-deferred-spell' for x in records)==2)
 previous={x['featId'] for stem in ['skill','general_exploration','general_defense','crafting'] for x in load(R/f'data/director/{stem}_feat_operating_proposal_internal.json')['records']}
 check('Disjoint from111 earlier proposal identities',len(previous)==111 and not previous&{x['featId'] for x in records})
 choicePools={}
 def choice(sid,cl,expected):
  s=spells[sid];row=s['classAccess'][cl];e=entries[sid]
  check(sid+' '+cl+' exact choice rank '+str(expected),row['rank']==expected)
  return {'id':sid,'name':s['name'],'rank':row['rank'],'school':row['school'],'sourceClass':cl,'fullOriginalClassAccessRow':row,
          'authoredStatus':e['authoredStatus'],'currentProcedureFile':e['procedureFile'],'currentWholeCardPointer':e['wholeCardPointer'],'sourceStatusUnchanged':s['status']}
 for cl in ['Bard','Cleric','Druid','Wizard']:
  rows=[choice(sid,cl,s['classAccess'][cl]['rank']) for sid,s in spells.items() if cl in s['classAccess'] and s['classAccess'][cl]['rank'] in [0,1]]
  choicePools[cl]={'status':'Existing exact class-rank membership, new feat access route proposed','choices':rows}
 for cl,cur in legacyCurricula.items():
  rows=[{**choice(sid,source,rank),'newFeatCurriculum':cl,'sourceClassIsNotAnAlias':True} for key,rank in [('cantrips',0),('rank1',1)] for sid,source in cur[key]]
